import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.BQGW-Zpy.js";const p=JSON.parse('{"title":"Pitch Strategy","description":"","frontmatter":{},"headers":[],"relativePath":"project/pitch-strategy.md","filePath":"project/pitch-strategy.md"}'),n={name:"project/pitch-strategy.md"};function s(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="pitch-strategy" tabindex="-1">Pitch Strategy <a class="header-anchor" href="#pitch-strategy" aria-label="Permalink to &quot;Pitch Strategy&quot;">​</a></h1><h3 id="_25-1-thirty-seconds" tabindex="-1">25.1 Thirty seconds <a class="header-anchor" href="#_25-1-thirty-seconds" aria-label="Permalink to &quot;25.1 Thirty seconds&quot;">​</a></h3><blockquote><p>Sending money abroad still takes days and hides its cost in the FX spread. The fintechs fixed the interface but pre-fund millions in every country. The crypto ramps fixed the settlement but hand the user a wallet. We do neither: the sender pays by card in euro, a licensed partner converts to a compliant stablecoin, it settles on Hedera in seconds, and a licensed local partner credits an ordinary bank account. Neither side ever sees a wallet. And because every licensed party&#39;s compliance check is hashed and anchored with a consensus timestamp, <em>&quot;the checks passed at this moment&quot;</em> becomes something a regulator can verify independently, instead of a row in someone&#39;s database.</p></blockquote><h3 id="_25-2-the-one-line" tabindex="-1">25.2 The one line <a class="header-anchor" href="#_25-2-the-one-line" aria-label="Permalink to &quot;25.2 The one line&quot;">​</a></h3><blockquote><p><strong>The licensed parties move the money. We make the chain provable.</strong></p></blockquote><h3 id="_25-3-questions-to-be-ready-for" tabindex="-1">25.3 Questions to be ready for <a class="header-anchor" href="#_25-3-questions-to-be-ready-for" aria-label="Permalink to &quot;25.3 Questions to be ready for&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>Answer</th></tr></thead><tbody><tr><td><strong>Aren&#39;t you an unlicensed payment institution?</strong></td><td>No. We never hold funds or crypto-assets. The licensed parties do. This is the agency model the EBA explicitly set out after March 2026.</td></tr><tr><td>Why not a database?</td><td>The parties are independently licensed and mutually distrusting. A record one of them owns is a record one of them can revise.</td></tr><tr><td>Why Hedera, not Solana?</td><td>Deterministic ~3s finality, fixed USD fees, Stablecoin Studio. Solana leads stablecoin payment volume and would win on finality after Alpenglow, we say so in <a href="./../architecture/settlement-layer.html">this section</a>. For a payment leg, knowing <em>when</em> it is final beats probably-faster.</td></tr><tr><td>So you cover every country?</td><td><strong>No.</strong> Coverage is licensing and partners. Blockchain does not open a corridor that has no licensed local partner.</td></tr><tr><td>Zero capital lock-up?</td><td><strong>No.</strong> The float moves to our payout partner. What we remove is the correspondent chain, one liquidity partner per corridor instead of a nostro network.</td></tr><tr><td>Where is the token?</td><td>Nowhere. Settlement uses USDC/EURC. Issuing our own EMT is legally reserved to EMIs.</td></tr><tr><td>Isn&#39;t this just Bridge/Ramp?</td><td>They leave a wallet in the flow, and none of them makes the compliance trail verifiable. That is the gap we occupy.</td></tr><tr><td>Who else benefits from this besides your users?</td><td>Regulators. Every anchor is readable by anyone through a public Mirror Node, no API key, no trusting our database. That&#39;s not just useful at our retail scale, the same pattern scales to how large financial institutions could make their own compliance trail independently verifiable. See <a href="./../legal/regulator-oversight.html">the regulator case</a>.</td></tr><tr><td>How do you know a transfer actually completed, not just your own backend saying so?</td><td>Once both the source-side and destination-side partner sign, Hedera&#39;s own consensus executes the completion, no code of ours triggers it. That&#39;s the Hedera Schedule Service: the message only reaches HCS once both signatures land.</td></tr><tr><td>Is it production ready?</td><td>No. Sandbox and testnet. <a href="./../analysis/innovation-ethics.html">this section</a> lists what it is not.</td></tr></tbody></table><hr>',8)])])}const y=t(n,[["render",s]]);export{p as __pageData,y as default};
